package hw09;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

public class RegistrationService {

    private final Connection connection;

    public RegistrationService() {
        try {
            connection = DriverManager.getConnection("jdbc:h2:mem:users;DB_CLOSE_DELAY=-1");
            try (Statement statement = connection.createStatement()) {
                statement.execute("create table users (" +
                        "id bigint generated by default as identity primary key, " +
                        "login varchar(100), " +
                        "password_hash varchar(200))");
            }
        } catch (SQLException e) {
            throw new IllegalStateException("не поднялась h2", e);
        }
    }

    public long register(String login, String password) {
        String hash = PasswordHasher.hash(password, "MD5", 1000);
        try (PreparedStatement insert = connection.prepareStatement(
                "insert into users (login, password_hash) values (?, ?)",
                Statement.RETURN_GENERATED_KEYS)) {
            insert.setString(1, login);
            insert.setString(2, hash);
            insert.executeUpdate();
            try (ResultSet keys = insert.getGeneratedKeys()) {
                keys.next();
                return keys.getLong(1);
            }
        } catch (SQLException e) {
            throw new IllegalStateException("не сохранился пользователь " + login, e);
        }
    }

    public void close() {
        try {
            connection.close();
        } catch (SQLException ignore) {
        }
    }
}
